import logging
from robot.libraries.BuiltIn import BuiltIn
from taf.sbts.oam.coam.admin import admin
from taf.rfrl.common_resources.ee_kpi.report_ee_kpi import ReportEEKpi, ReportESMKpi


def get_ee_counters(connection=None, ee_counters=None, timeout=60):
    """
    Get EE counters
    :param connection: admin Connection object or string name alias.
    :param ee_counters: List of counter names eg. ['M40004C2', 'M40003C4']
                     If None, then all available EE counters will be used for reporting.
    :param timeout: Timeout for the command
    :return: Counter values eg:
        {
            "BTS": {
                "MRBTS-78034": {
                    "EQM-1": {
                        "APEQM-1": {
                            "CABINET-1": {
                                "SMOD-1": {
                                    "SBTS_SM_Energy_Monitoring": {
                                        "M40004C2": {
                                            "1724657460": 160067,
                                            "1724659200": 160229,
                                        }
                                    }
                                }
                            },
                            "RMOD-1": {
                                "SBTS_RFM_Energy_Monitoring": {
                                    "M40003C4": {
                                        "1724657460": 35843,
                                        "1724659200": 37027,
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

    """
    # System KPI
    # M40002C0
    # M40002C1
    # M40002C2

    # SM KPI
    # M40004C0
    # M40004C1
    # M40004C2
    # M40004C3

    # BBMOD KPI
    # M40028C0
    # M40028C1
    # M40028C2
    # M40028C3

    # RF KPI
    # M40003C2
    # M40003C3
    # M40003C4
    # M40003C5

    all_ee_counters = ['M40002C0', 'M40002C1', 'M40002C2',
                       'M40004C0', 'M40004C1', 'M40004C2', 'M40004C3',
                       'M40028C0', 'M40028C1', 'M40028C2', 'M40028C3',
                       'M40003C2', 'M40003C3', 'M40003C4', 'M40003C5']
    if ee_counters is None:
        ee_counters = all_ee_counters
    else:
        for counter in ee_counters:
            if counter not in all_ee_counters:
                raise ValueError(f"Counter {counter} is not supported")

    counter = admin().get_pm_counters(counter_ids=','.join(ee_counters), timeout=timeout, connection=connection)
    return counter


def get_detailed_bts_info(connection=None, timeout=30):
    bbmods_info = {}
    admin_cli = admin()
    bts_info = admin_cli.get_bts_info(connection=connection, timeout=timeout)
    for bbmod in bts_info['basebandModules']:
        bbmod_runtime_dn = bbmod['id']['internal']
        bbmod_conf_dn = bbmod['id']['configuration']
        bbmods_info[bbmod_conf_dn] = admin_cli.get_parameters(dist_name=bbmod_runtime_dn, connection=connection)
    return {'bts_info': bts_info, 'bbmods_info': bbmods_info}


def report_ee_kpi(ee_counters_before, ee_counters_after, test_model_params, detailed_bts_info, ee_kpi_targets=None,
                  check_load_type=True, required_intervals=4, pm_interval=900):
    """
    Report EE KPI to ReP. Results are presented in ReP under link:
        https://rep-portal.wroclaw.nsn-rdnet.net/reports/kpi/

    :param ee_counters_before: Counters collected by get_ee_counters before running Test Model
    :param ee_counters_after: Counters collected by get_ee_counters after running Test Model
    :param test_model_params: list of dicts (or single dict) of Test Model parameters. should contain at least:
            test_model_params = [
                        {
                         'dist_name': '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/NRBTS_R-1/NRCELL_R-0',
                         'test_model': 'NR-FR1-TM1.1.ETSI',
                         'p_max': 17,
                         'load_type': 'slotWiseLoad',
                         'load_level': 'load_70',
                         'load_level_name': 'Full'
                        },
                        {
                         'dist_name': '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/NRBTS_R-1/NRCELL_R-1',
                         'test_model': 'NR-FR1-TM1.1.ETSI',
                         'p_max': 21,
                         'load_type': 'slotWiseLoad',
                         'load_level': 'load_70',
                         'load_level_name': 'Full'
                        },
                        .....
            ]
    :param detailed_bts_info: results of 'get_detailed_bts_info' method(taf.rfrl.common_resources.ee_kpi.interface).
    :param ee_kpi_targets: dict with KPI targets eg.
            ee_kpi_targets = {
                'M40004C2_Idle': 100,
                'M40004C2_Low': 30,
            }
    :param check_load_type: check if load_type is the same for all test_model_params
    :param required_intervals: number of PM intervals to calculate KPI value
    :param pm_interval: PM interval in seconds, default is 900 seconds (15 minutes)
    :return: list of dicts with KPI results(in the same format as seen in ReP JSON file)
    """

    if ee_kpi_targets is None:
        ee_kpi_targets = BuiltIn().get_variable_value('${{{}}}'.format('EE_KPI_TARGETS'), None)

    return ReportEEKpi().report_ee_kpi(ee_counters_before, ee_counters_after, test_model_params, detailed_bts_info,
                                       ee_kpi_targets, check_load_type, required_intervals, pm_interval)


def report_esm_kpi(esm_counters_before, esm_counters_after, cells_statuses, rus_statuses, test_state,
                   detailed_bts_info, esm_kpi_targets=None, required_intervals=4, pm_interval=900):
    """
    Report ESM KPI to ReP. Results are presented in ReP under link:
        https://rep-portal.wroclaw.nsn-rdnet.net/reports/kpi/
    :param esm_counters_before: Counters collected by get_ee_counters before running ESM
    :param esm_counters_after: Counters collected by get_ee_counters after running
    :param cells_statuses: dict of cells statuses collected after running ESM
            cells_statuses = {
                'LNCEL-1': {'energy_saving_state': 'energySaving'},
                'LNCEL-2': {'energy_saving_state': 'notEnergySaving'},
                ....
            }
    :param rus_statuses: dict of RUs statuses collected after running ESM
            rus_statuses = {
                'RMOD-1': {'power_state': 'SLEEP'},
                'RMOD-2': {'power_state': 'AWAKE'},
                ....
            }
    :param test_state: string
            test_state = 'OnAirBefore' / 'ESM1' / 'ESM2' / 'OnAirAfter'
    :param detailed_bts_info: results of 'get_detailed_bts_info' method
            (taf.rfrl.common_resources.ee_kpi.interface).
    :param esm_kpi_targets: dict with KPI targets eg.
            esm_kpi_targets = {
                'M40004C2_ESM1': 100,
                'M40004C2_ESM2': 30,
            }
    :param required_intervals: number of PM intervals to calculate KPI value
    :param pm_interval: PM interval in seconds, default is 900 seconds(15 minutes)
    :return: list of dicts with KPI results(in the same format which is visible in ReP JSON file)
    """
    if esm_kpi_targets is None:
        esm_kpi_targets = BuiltIn().get_variable_value('${{{}}}'.format('ESM_KPI_TARGETS'), None)

    return ReportESMKpi().report_esm_kpi(esm_counters_before, esm_counters_after, cells_statuses, rus_statuses,
                                         test_state, detailed_bts_info, esm_kpi_targets, required_intervals,
                                         pm_interval)


def set_ee_target(kpi_name, target):
    _set_target(kpi_name, target, 'EE_KPI_TARGETS')


def set_esm_target(kpi_name, target):
    _set_target(kpi_name, target, 'ESM_KPI_TARGETS')


def _set_target(kpi_name, target, variable_name):
    """
    Set target for KPI.
    Target you can pass directly in report_ee_kpi method or set it before, using this method.
    """
    kpi_targets = BuiltIn().get_variable_value('${{{}}}'.format(variable_name), None)
    if not kpi_targets:
        kpi_targets = {kpi_name: target}
        BuiltIn().set_test_variable('${{{}}}'.format(variable_name), kpi_targets)
    else:
        kpi_targets[kpi_name] = target

    logging.debug("CURRENT TARGETS {}".format(kpi_targets))
